package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.DynamicallyRegisteredVO;

class DynamicallyRegisteredValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of dynamically registered of oauth client")
  void test_dynamically_registered_value_holder_assign_plain_value() {
    Object holder = new Object();
    DynamicallyRegisteredValueHolder<Object> value = new DynamicallyRegisteredValueHolder<>(holder);
    Assertions.assertSame(holder, value.dynamicallyRegistered(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getDynamicallyRegisteredValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getDynamicallyRegistered().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.dynamicallyRegisteredNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getDynamicallyRegisteredValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of dynamically registered of oauth client")
  void test_dynamically_registered_value_holder_assign_value_object() {
    Object holder = new Object();
    DynamicallyRegisteredValueHolder<Object> value = new DynamicallyRegisteredValueHolder<>(holder);
    DynamicallyRegisteredVO vo = DynamicallyRegisteredVO.from(true);
    Assertions.assertFalse(value.getDynamicallyRegisteredValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.dynamicallyRegistered(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getDynamicallyRegisteredValue().orElseThrow());
    Assertions.assertSame(holder, value.dynamicallyRegistered(Optional.empty()));
    Assertions.assertFalse(value.getDynamicallyRegisteredValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.dynamicallyRegistered(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDynamicallyRegisteredValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of dynamically registered of oauth client against the original")
  void test_dynamically_registered_value_holder_read() {
    Object holder = new Object();
    DynamicallyRegisteredValueHolder<Object> value = new DynamicallyRegisteredValueHolder<>(holder);
    DynamicallyRegisteredVO vo = DynamicallyRegisteredVO.from(true);
    DynamicallyRegisteredVO other = DynamicallyRegisteredVO.from(true);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getDynamicallyRegisteredValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDynamicallyRegistered(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDynamicallyRegistered(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.dynamicallyRegistered(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDynamicallyRegistered(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDynamicallyRegistered(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of dynamically registered of oauth client")
  void test_dynamically_registered_value_holder_unset() {
    Object holder = new Object();
    DynamicallyRegisteredValueHolder<Object> value = new DynamicallyRegisteredValueHolder<>(holder);
    DynamicallyRegisteredVO vo = DynamicallyRegisteredVO.from(true);
    value.dynamicallyRegistered(vo);
    Assertions.assertSame(holder,
        value.unsetDynamicallyRegisteredIfMatches("dynamicallyRegistered_other"));
    Assertions.assertTrue(value.getDynamicallyRegisteredValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetDynamicallyRegisteredIfMatches("dynamicallyRegistered"));
    Assertions.assertFalse(value.getDynamicallyRegisteredValue().isPresent(),
        "The field name must clear the value");
    value.dynamicallyRegistered(vo);
    Assertions.assertSame(holder, value.unsetDynamicallyRegistered());
    Assertions.assertFalse(value.getDynamicallyRegisteredValue().isPresent(),
        "Unset must clear the value");
  }
}
